  "Interactive API Docs": { eng: "Interactive API Docs", deu: "Interaktive API-Doku", esp: "Documentación interactiva de la API", fra: "Documentation interactive de l'API", ita: "Documentazione interattiva dell'API", jpn: "対話型 API ドキュメント", kor: "대화형 API 문서", pol: "Interaktywna dokumentacja API", ptb: "Documentação interativa da API", rus: "Интерактивная документация API", spa: "Documentación interactiva de la API", tha: "เอกสาร API แบบโต้ตอบ", tur: "Etkileşimli API Belgeleri", zhs: "交互式 API 文档", zht: "互動式 API 文件" },
  "Full Swagger/OpenAPI documentation with try-it-out functionality.": { eng: "Full Swagger/OpenAPI documentation with try-it-out functionality.", deu: "Vollständige Swagger/OpenAPI-Dokumentation mit Ausprobieren-Funktion.", esp: "Documentación completa Swagger/OpenAPI con función para probar las llamadas.", fra: "Documentation Swagger/OpenAPI complète avec fonction d'essai.", ita: "Documentazione Swagger/OpenAPI completa con funzione di prova.", jpn: "その場で試せる機能付きの完全な Swagger/OpenAPI ドキュメント。", kor: "직접 실행해 볼 수 있는 전체 Swagger/OpenAPI 문서.", pol: "Pełna dokumentacja Swagger/OpenAPI z możliwością wypróbowania.", ptb: "Documentação completa Swagger/OpenAPI com função de teste.", rus: "Полная документация Swagger/OpenAPI с возможностью попробовать запросы.", spa: "Documentación completa Swagger/OpenAPI con función para probar las llamadas.", tha: "เอกสาร Swagger/OpenAPI ฉบับเต็มพร้อมฟังก์ชันทดลองใช้", tur: "Deneme özelliğiyle eksiksiz Swagger/OpenAPI belgeleri.", zhs: "完整的 Swagger/OpenAPI 文档，支持在线试用。", zht: "完整的 Swagger/OpenAPI 文件，支援線上試用。" },
  "Open API Docs →": { eng: "Open API Docs →", deu: "API-Doku öffnen →", esp: "Abrir la documentación de la API →", fra: "Ouvrir la documentation de l'API →", ita: "Apri la documentazione dell'API →", jpn: "API ドキュメントを開く →", kor: "API 문서 열기 →", pol: "Otwórz dokumentację API →", ptb: "Abrir documentação da API →", rus: "Открыть документацию API →", spa: "Abrir la documentación de la API →", tha: "เปิดเอกสาร API →", tur: "API Belgelerini Aç →", zhs: "打开 API 文档 →", zht: "打開 API 文件 →" },
